-- Автоматически сгенерировано из «cpu new 2.csv» — база процессоров для страницы cpu.html (таблица cpus)
-- Импортировать через phpMyAdmin в ту же базу, что и gpus (api/config.php).
SET NAMES utf8mb4;

-- Повторный импорт безопасен: старая таблица удаляется, дублей не будет.
DROP TABLE IF EXISTS cpus;
CREATE TABLE cpus (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  brand VARCHAR(32) NOT NULL,
  cpu_type VARCHAR(64),
  perf DECIMAL(10,2),
  arch_name VARCHAR(255),
  socket VARCHAR(64),
  rel_year SMALLINT,
  rel_month TINYINT,
  cores SMALLINT,
  threads SMALLINT,
  base_clock DECIMAL(6,2),
  boost_clock DECIMAL(6,2),
  cache_l1 VARCHAR(64),
  cache_l2 VARCHAR(64),
  cache_l3 VARCHAR(64),
  lithography VARCHAR(64),
  max_temp DECIMAL(6,2),
  tdp DECIMAL(8,2),
  mem_type VARCHAR(64),
  igpu VARCHAR(255),
  pci_rev VARCHAR(32),
  pci_lanes VARCHAR(32),
  hits INT NOT NULL DEFAULT 0,
  INDEX(name), INDEX(brand), INDEX(rel_year), INDEX(perf)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;





















